/**
 * Parses a value as a base-10 integer and clamps it inclusively between min and max.
 *
 * @param {unknown} value - The value to parse (can be a string like '8', number, etc.)
 * @param {number} fallback - The fallback value to return when parsing fails
 * @param {number} min - The minimum inclusive bound
 * @param {number} max - The maximum inclusive bound
 * @returns {number} The parsed and clamped integer, or fallback if parsing fails
 */
export function clampInteger(value, fallback, min, max) {
  // Try to parse as integer
  let parsed;
  if (typeof value === 'string') {
    // Only parse if the string contains valid integer characters
    // Reject empty strings, floats, and non-numeric strings
    const trimmed = value.trim();
    if (trimmed === '' || !/^-?\d+$/.test(trimmed)) {
      return fallback;
    }
    parsed = parseInt(trimmed, 10);
  } else if (typeof value === 'number') {
    // Reject NaN and non-integer numbers
    if (!Number.isInteger(value) || Number.isNaN(value)) {
      return fallback;
    }
    parsed = value;
  } else {
    // For any other type, return fallback
    return fallback;
  }

  // Check if parsing resulted in a valid integer
  if (Number.isNaN(parsed)) {
    return fallback;
  }

  // Clamp the value between min and max (inclusive)
  if (parsed < min) return min;
  if (parsed > max) return max;
  return parsed;
}

import { clampInteger } from './src/lib.mjs';
import assert from 'node:assert';

// Test cases from the requirement
console.log('String 8:', clampInteger('8', 0, 1, 10));
console.log('String 0:', clampInteger('0', 0, 1, 10));
console.log('Number 5:', clampInteger(5, 0, 1, 10));
console.log('Number 0:', clampInteger(0, 0, 1, 10));
console.log('Invalid str:', clampInteger('abc', 0, 1, 10));
console.log('Float str:', clampInteger('8.5', 0, 1, 10));
console.log('Empty str:', clampInteger('', 0, 1, 10));
console.log('Below min:', clampInteger('0', 5, 1, 10));
console.log('Above max:', clampInteger('15', 5, 1, 10));
console.log('Float num:', clampInteger(8.5, 0, 1, 10));
console.log('NaN:', clampInteger(NaN, 0, 1, 10));
console.log('Null:', clampInteger(null, 0, 1, 10));
console.log('Undefined:', clampInteger(undefined, 0, 1, 10));
console.log('Negative:', clampInteger('-5', 0, -10, 10));
console.log('Negative clamp:', clampInteger('-15', 0, -10, 10));
console.log('Whitespace:', clampInteger('  42  ', 0, 1, 100));
console.log('Zero valid:', clampInteger('0', -1, 0, 5));

// Assertions
assert.strictEqual(clampInteger('8', 0, 1, 10), 8);
assert.strictEqual(clampInteger('0', 0, 1, 10), 1); // clamped to min
assert.strictEqual(clampInteger(5, 0, 1, 10), 5);
assert.strictEqual(clampInteger(0, 0, 1, 10), 1); // clamped to min
assert.strictEqual(clampInteger('abc', 0, 1, 10), 0); // fallback
assert.strictEqual(clampInteger('8.5', 0, 1, 10), 0); // fallback - not integer
assert.strictEqual(clampInteger('', 0, 1, 10), 0); // fallback
assert.strictEqual(clampInteger('0', 5, 1, 10), 1); // clamped to min
assert.strictEqual(clampInteger('15', 5, 1, 10), 10); // clamped to max
assert.strictEqual(clampInteger(8.5, 0, 1, 10), 0); // fallback - not integer
assert.strictEqual(clampInteger(NaN, 0, 1, 10), 0); // fallback
assert.strictEqual(clampInteger(null, 0, 1, 10), 0); // fallback
assert.strictEqual(clampInteger(undefined, 0, 1, 10), 0); // fallback
assert.strictEqual(clampInteger('-5', 0, -10, 10), -5); // negative
assert.strictEqual(clampInteger('-15', 0, -10, 10), -10); // negative clamp
assert.strictEqual(clampInteger('  42  ', 0, 1, 100), 42); // whitespace
assert.strictEqual(clampInteger('0', -1, 0, 5), 0); // explicit zero is valid

console.log('\nAll assertions passed!');
